    --bg-card: #ffffff;
    --border-color: #e5e7eb;
    --focus-ring: #3b82f6;
    --container-width: 800px;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
    line-height: 1.5;
    color: var(--text-main);
    background-color: var(--bg-page);
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 1.5rem;
}

/* Skip link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--primary-color);
    color: white;
    padding: 8px;
    z-index: 100;
    transition: top 0.2s;
    text-decoration: none;
}

.skip-link:focus {
    top: 0;
}

/* Header */
header {
    background: var(--bg-card);
    border-bottom: 1px solid var(--border-color);
    padding: 3rem 0;
    text-align: center;
}

header h1 {
    font-size: 2.5rem;
    font-weight: 800;
    margin-bottom: 0.5rem;
    color: var(--text-main);
}

header p {
    font-size: 1.125rem;
    color: var(--text-muted);
}

/* Main content */
main {
    padding: 3rem 0;
}

.faq-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.example {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 0.75rem;
    overflow: hidden;
    transition: box-shadow 0.2s;
}

.example:hover {
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.example h3 {
    font-size: 1.125rem;
    font-weight: 600;
}

.example button {
    width: 100%;
    text-align: left;
    padding: 1.25rem 1.5rem;
    background: none;
    border: none;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    color: var(--text-main);
    font-family: inherit;
    font-size: inherit;
    font-weight: inherit;
}

.example button:focus-visible {
    outline: 2px solid var(--focus-ring);
    outline-offset: -2px;
}

.example .icon {
    width: 20px;
    height: 20px;
    position: relative;
    flex-shrink: 0;
    transition: transform 0.3s;
}

.example .icon::before,
.example .icon::after {
    content: '';
    position: absolute;
    background-color: var(--text-muted);
    border-radius: 2px;
    transition: transform 0.3s;
}

/* Horizontal line */
.example .icon::before {
    width: 12px;
    height: 2px;
    top: 9px;
    left: 4px;
}

/* Vertical line (makes it a plus) */
.example .icon::after {
    width: 2px;
    height: 12px;
    top: 4px;
    left: 9px;
}

.example button[aria-expanded="true"] .icon {
    transform: rotate(45deg); /* Turns plus into an X or just rotates it */
}

/* Change icon when expanded to just a minus? 
   Actually, rotating the plus 45 deg makes it an X. 
   Alternatively, hide the vertical bar. 
*/
.example button[aria-expanded="true"] .icon::after {
    transform: scaleY(0);
}

.details {
    padding: 0 1.5rem 1.25rem;
    color: var(--text-muted);
    font-size: 1rem;
    border-top: 1px solid transparent;
}

.example button[aria-expanded="true"] + .details {
    border-top-color: var(--border-color);
    padding-top: 1.25rem;
}

/* Footer */
footer {
    padding: 2rem 0;
    text-align: center;
    color: var(--text-muted);
    font-size: 0.875rem;
}

/* Media Queries */
@media (max-width: 640px) {
    header h1 {
        font-size: 2rem;
    }

    .example button {
        padding: 1rem;
    }

    .details {
        padding: 0 1rem 1rem;
    }
}

/* Accessibility: Reduced Motion */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}
