 * 
 * Requirements:
 * - Wrap each question/answer section in a div with class "example".
 * - Give the container for the controlled content a class of "details".
 */

document.addEventListener('DOMContentLoaded', () => {
    const faqButtons = document.querySelectorAll('.example button[aria-expanded]');

    faqButtons.forEach(button => {
        // The panel is the next sibling element with class "details"
        // In our HTML structure, it's the element immediately after the h3 containing the button
        const panel = button.parentElement.nextElementSibling;

        // Initialize state: collapsed by default
        // We set this in JS so that content remains visible if JS is disabled/fails
        button.setAttribute('aria-expanded', 'false');
        if (panel) {
            panel.hidden = true;
        }

        button.addEventListener('click', () => {
            const isExpanded = button.getAttribute('aria-expanded') === 'true';

            // Toggle the state
            button.setAttribute('aria-expanded', !isExpanded);

            if (panel) {
                panel.hidden = isExpanded;
            }
        });
    });
});
